%x=x'; 
i=input('请输入需要修改的i：'); 
j=input('请输入需要修改的j：'); 

x(i,j)=input(' '); 
x(j,i)=input(' '); 
for i=1:6 
 summ(i)=sum(x(i,:)); 
end 
youxiangtu=zeros(6,6); 
for i=1:6 
 for j=1:6 
 d(i,j)=x(i,j)/max(summ);%正规化直接影响矩阵； 
 if x(i,j)>0 
 youxiangtu(i,j)=1; 
 end 
 end 
end 
t=d*(1-d)^(-1); 
byxd=abs(sum(t));%被影响度 
yxd=abs(sum((t')));%影响度 
yyd=yxd-byxd;%原因度 
yyd=yyd/sum(yyd); 
zxd=yxd+byxd;%中心度 


c=zeros(6,6); 
tv=0.5; 
for i=1:6 
 if zxd<tv 
 youxiangtu(i,:)=0; 
 end 
end 


for i=1:6 
 for j=1:6 
 if youxiangtu(i,j)==1&&yyd(i)>0&& zxd(i)>=tv 
 c(i,j)=1; 
 end 

 if youxiangtu(i,j)==1&&yyd(j)>0&& zxd(j)>=tv 
 c(j,i)=1; 
 end
